export type SubscribeResult =
  | { kind: "subscribed"; subscriberId: string }
  | { kind: "email_error"; message: string }
  | { kind: "topic_error"; message: string }
  | { kind: "connection_error"; message: string }
  | { kind: "already_subscribed"; message: string }
